/**
 * Detect current page from the URL filename.
 */
function getCurrentPage() {
    const path = window.location.pathname;
    const file = path.split("/").pop().replace(".html", "").toLowerCase();
    const map = { "": "overview", "index": "overview" };
    return map[file] !== undefined ? map[file] : file;
}


