/**
 * Generate realistic 24-hour forecast data with natural fluctuations.
 */
function generateForecastData() {
    const baseProfile = [
        4820, 4650, 4480, 4350, 4280, 4420, 4750, 5320,
        5980, 6540, 7120, 7680, 8050, 8280, 8470, 8420,
        8190, 7860, 7480, 7050, 6620, 6180, 5720, 5280
    ];
    const temps = [
        31, 30, 29, 28, 28, 29, 31, 33,
        35, 36, 37, 38, 38, 38, 38, 37,
        36, 35, 34, 33, 32, 32, 31, 31
    ];
    return baseProfile.map((predicted, i) => {
        const noise = (Math.random() - 0.5) * 160;
        const actual = i <= 15 ? Math.round(predicted + noise) : null;
        const band = Math.round(80 + Math.random() * 100);
        return {
            time: `${String(i).padStart(2, "0")}:00`,
            predicted,
            lower: predicted - band,
            upper: predicted + band,
            actual,
            temperature: temps[i],
        };
    });
}

