// --- API Functions -------------------------------------------------------

function simulateLatency(ms) {
    // Artificial latency removed for faster page switching
    return Promise.resolve();
}

async function fetchForecast() {
    if (USE_MOCK_DATA) { await simulateLatency(300); return mockForecastData; }
    const res = await fetch(`${CONFIG.baseUrl}/forecast`);
    if (!res.ok) throw new Error("Forecast API failed");
    return await res.json();
}

async function fetchWeather() {
    if (USE_MOCK_DATA) return mockWeatherData;
    try {
        var r = await fetch(CONFIG.baseUrl + "/weather");
        if (!r.ok) throw new Error("API error");
        return await r.json();
    } catch (e) { console.error(e); return mockWeatherData; }
}

async function fetchMetrics() {
    if (USE_MOCK_DATA) return { maeMw: 142, rmseMw: 198, mapePct: 2.4, baselineMaeMw: 250, improvementPct: 40, errorBandMw: 120 };
    try {
        var r = await fetch(CONFIG.baseUrl + "/metrics");
        if (!r.ok) throw new Error("API error");
        return await r.json();
    } catch (e) {
        console.error("Failed to fetch metrics:", e);
        return { maeMw: 142, rmseMw: 198, mapePct: 2.4, baselineMaeMw: 250, improvementPct: 40, errorBandMw: 120 };
    }
}

async function fetchRisk() {
    if (USE_MOCK_DATA) { await simulateLatency(200); return mockRiskData; }
    const res = await fetch(`${CONFIG.baseUrl}/risk`);
    if (!res.ok) throw new Error("Risk API failed");
    return await res.json();
}

async function fetchInsights() {
    if (USE_MOCK_DATA) { await simulateLatency(250); return mockInsightsData; }
    const res = await fetch(`${CONFIG.baseUrl}/insights`);
    if (!res.ok) throw new Error("Insights API failed");
    return await res.json();
}

async function runWhatIfScenario(parameters) {
    if (USE_MOCK_DATA) { await simulateLatency(700); return calculateLocalWhatIf(parameters); }
    const res = await fetch(`${CONFIG.baseUrl}/what-if`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(parameters),
    });
    if (!res.ok) throw new Error("What-If API failed");
    return await res.json();
}


