function $(sel)  { return document.querySelector(sel); }
function $$(sel) { return document.querySelectorAll(sel); }

function formatNumber(num) {
    return num.toLocaleString("en-IN");
}

function animateNumber(el, target, duration, decimals) {
    duration = duration || CONFIG.animationDuration;
    decimals = decimals || 0;
    const startTime = performance.now();
    (function update(now) {
        const progress = Math.min((now - startTime) / duration, 1);
        const eased = 1 - Math.pow(1 - progress, 3);
        const current = target * eased;
        el.textContent = decimals > 0
            ? formatNumber(parseFloat(current.toFixed(decimals)))
            : formatNumber(Math.round(current));
        if (progress < 1) requestAnimationFrame(update);
    })(performance.now());
}

function showToast(message, type) {
    type = type || "info";
    const container = $("#toastContainer");
    if (!container) return;
    const iconMap = { success: "check-circle", error: "alert-circle", info: "info", warning: "alert-triangle" };
    const toast = document.createElement("div");
    toast.className = "toast " + type;
    toast.innerHTML =
        '<i data-lucide="' + iconMap[type] + '" class="toast-icon" aria-hidden="true"></i>' +
        '<span class="toast-text">' + message + '</span>';
    container.appendChild(toast);
    if (typeof lucide !== 'undefined') lucide.createIcons({ nodes: [toast] });
    setTimeout(function () {
        toast.classList.add("removing");
        setTimeout(function () { toast.remove(); }, 300);
    }, CONFIG.toastDuration);
}

function updateDateTime() {
    var now = new Date();
    var dateEl = $("#headerDate");
    var timeEl = $("#headerTime");
    if (dateEl) dateEl.textContent = now.toLocaleDateString("en-IN", { weekday: "short", day: "numeric", month: "short", year: "numeric" });
    if (timeEl) timeEl.textContent = now.toLocaleTimeString("en-IN", { hour: "2-digit", minute: "2-digit", second: "2-digit", hour12: false });
}

function drawSparkline(canvasId, data, color) {
    color = color || "#2dd4bf";
    var canvas = document.getElementById(canvasId);
    if (!canvas) return;
    var ctx = canvas.getContext("2d");
    var w = canvas.width, h = canvas.height;
    var dpr = window.devicePixelRatio || 1;
    canvas.width = w * dpr; canvas.height = h * dpr;
    canvas.style.width = w + "px"; canvas.style.height = h + "px";
    ctx.scale(dpr, dpr);
    ctx.clearRect(0, 0, w, h);
    var min = Math.min.apply(null, data), max = Math.max.apply(null, data);
    var range = max - min || 1, step = w / (data.length - 1);
    ctx.beginPath();
    data.forEach(function (val, i) {
        var x = i * step, y = h - ((val - min) / range) * (h - 4) - 2;
        i === 0 ? ctx.moveTo(x, y) : ctx.lineTo(x, y);
    });
    ctx.strokeStyle = color; ctx.lineWidth = 1.5; ctx.stroke();
    ctx.lineTo((data.length - 1) * step, h); ctx.lineTo(0, h); ctx.closePath();
    var grad = ctx.createLinearGradient(0, 0, 0, h);
    grad.addColorStop(0, color + "33"); grad.addColorStop(1, "transparent");
    ctx.fillStyle = grad; ctx.fill();
}


// =============================================
// 6. RISK CALCULATIONS
// =============================================

/**
 * Central risk calculation — used everywhere.
 * Do NOT duplicate this logic.
 */
function calculateRisk(utilization) {
    if (utilization > 100) return { level: "CRITICAL", class: "critical" };
    if (utilization >= 85)  return { level: "HIGH",     class: "high"     };
    if (utilization >= 70)  return { level: "WATCH",    class: "watch"    };
    return { level: "NORMAL", class: "normal" };
}

/**
 * Deterministic local what-if model.
 * Responds to all four slider inputs.
 */
function calculateLocalWhatIf(params) {
    var baselinePeak = 8470, baseTemp = 38, baseHumidity = 61, baseSolar = 620;
    var tempDelta     = (params.temperature - baseTemp) * 110;
    var humidityDelta = (params.humidity - baseHumidity) * 8;
    var solarDelta    = -(params.solarGeneration - baseSolar);
    var growthDelta   = baselinePeak * (params.demandGrowth / 100);
    var totalChange   = Math.round(tempDelta + humidityDelta + solarDelta + growthDelta);
    var simulatedPeak = baselinePeak + totalChange;
    var utilization   = parseFloat(((simulatedPeak / CONFIG.capacity) * 100).toFixed(1));
    var risk = calculateRisk(utilization);
    return {
        baselinePeak: baselinePeak,
        simulatedPeak: simulatedPeak,
        change: totalChange,
        utilization: utilization,
        risk: risk.level,
        riskClass: risk.class,
        forecast: mockForecastData.forecast.map(function (row) {
            var hourFactor = row.predicted / baselinePeak;
            return Object.assign({}, row, { simulated: Math.round(row.predicted + totalChange * hourFactor) });
        }),
    };
}


