function renderRiskGauge(utilization) {
    var canvas = document.getElementById("riskGauge");
    if (!canvas) return;
    var ctx = canvas.getContext("2d");
    var dpr = window.devicePixelRatio || 1;
    var w = 280, h = 180;
    canvas.width = w * dpr; canvas.height = h * dpr;
    canvas.style.width = w + "px"; canvas.style.height = h + "px";
    ctx.scale(dpr, dpr); ctx.clearRect(0, 0, w, h);
    var cx = w / 2, cy = h - 20, radius = 110, lw = 16;
    var startA = Math.PI, endA = 2 * Math.PI;
    ctx.beginPath(); ctx.arc(cx, cy, radius, startA, endA);
    ctx.strokeStyle = "#1e2940"; ctx.lineWidth = lw; ctx.lineCap = "round"; ctx.stroke();
    var segs = [{ e: 0.7, c: "#22c55e" }, { e: 0.85, c: "#ffb74d" }, { e: 1.0, c: "#e67e22" }, { e: 1.15, c: "#ef4444" }];
    var prev = 0;
    segs.forEach(function (s) {
        ctx.beginPath(); ctx.arc(cx, cy, radius, startA + (endA - startA) * (prev / 1.15), startA + (endA - startA) * (s.e / 1.15));
        ctx.strokeStyle = s.c; ctx.lineWidth = lw; ctx.lineCap = "butt"; ctx.stroke(); prev = s.e;
    });
    var clamped = Math.min(utilization, 115) / 115;
    var na = startA + (endA - startA) * clamped;
    ctx.beginPath(); ctx.moveTo(cx, cy); ctx.lineTo(cx + Math.cos(na) * (radius - 25), cy + Math.sin(na) * (radius - 25));
    ctx.strokeStyle = "#e8ecf4"; ctx.lineWidth = 2.5; ctx.lineCap = "round"; ctx.stroke();
    ctx.beginPath(); ctx.arc(cx, cy, 5, 0, 2 * Math.PI); ctx.fillStyle = "#e8ecf4"; ctx.fill();
}

function renderOffsetDonut(solar, gross) {
    var canvas = document.getElementById("offsetDonut");
    if (!canvas) return;
    var ctx = canvas.getContext("2d"), dpr = window.devicePixelRatio || 1, size = 140;
    canvas.width = size * dpr; canvas.height = size * dpr;
    canvas.style.width = size + "px"; canvas.style.height = size + "px";
    ctx.scale(dpr, dpr); ctx.clearRect(0, 0, size, size);
    var cx = size / 2, cy = size / 2, r = 52, lw = 14, pct = solar / gross;
    ctx.beginPath(); ctx.arc(cx, cy, r, 0, 2 * Math.PI); ctx.strokeStyle = "#1e2940"; ctx.lineWidth = lw; ctx.stroke();
    ctx.beginPath(); ctx.arc(cx, cy, r, -Math.PI / 2, -Math.PI / 2 + 2 * Math.PI * pct);
    ctx.strokeStyle = "#22c55e"; ctx.lineWidth = lw; ctx.lineCap = "round"; ctx.stroke();
    ctx.fillStyle = "#e8ecf4"; ctx.font = "bold 16px 'JetBrains Mono', monospace";
    ctx.textAlign = "center"; ctx.textBaseline = "middle";
    ctx.fillText((pct * 100).toFixed(1) + "%", cx, cy - 6);
    ctx.font = "10px 'Inter', sans-serif"; ctx.fillStyle = "#5a6a85"; ctx.fillText("Solar", cx, cy + 12);
}

