function renderKPIs(forecast, risk) {
    var loadEl = document.querySelector("#kpi-load .kpi-number");
    if (loadEl) animateNumber(loadEl, forecast.currentLoad);
    var peakEl = document.querySelector("#kpi-peak .kpi-number");
    if (peakEl) animateNumber(peakEl, forecast.peakDemand);
    var utilPct = parseFloat(((forecast.peakDemand / forecast.capacity) * 100).toFixed(1));
    var utilEl = document.querySelector("#kpi-util .kpi-number");
    if (utilEl) animateNumber(utilEl, utilPct, CONFIG.animationDuration, 1);
    setTimeout(function () { var bar = $("#utilProgress"); if (bar) bar.style.width = Math.min(utilPct, 100) + "%"; }, 100);
    var riskResult = calculateRisk(utilPct);
    var badge = $("#riskBadge");
    if (badge) { badge.textContent = riskResult.level; badge.className = "risk-badge " + riskResult.class; }
    setTimeout(function () { var fill = $("#riskFill"); if (fill) fill.style.width = Math.min(utilPct, 100) + "%"; }, 100);
    var actuals = forecast.forecast.map(d => d.actual).filter(v => v !== null);
    if (actuals.length === 0) actuals = forecast.forecast.map(d => d.predicted).slice(0, 8);
    var predicted = forecast.forecast.map(d => d.predicted);
    drawSparkline("sparkLoad", actuals, "#2dd4bf");
    drawSparkline("sparkPeak", predicted, "#a78bfa");
}

