    var offsetNet = $("#offsetNet"); if (offsetNet) offsetNet.textContent = formatNumber(forecast.peakDemand - weather.solarGeneration) + " MW";
    var offsetPercent = $("#offsetPercent"); if (offsetPercent) offsetPercent.textContent = ((weather.solarGeneration / forecast.peakDemand) * 100).toFixed(1) + "%";
