// =============================================
// 10. WHAT-IF SIMULATION
// =============================================

function getSliderValues() {
    return {
        temperature: parseFloat($("#sliderTemp").value),
        humidity: parseFloat($("#sliderHumidity").value),
        solarGeneration: parseFloat($("#sliderSolar").value),
        demandGrowth: parseFloat($("#sliderGrowth").value),
    };
}

function updateSliderDisplay() {
    var v = getSliderValues();
    $("#sliderTempVal").textContent     = v.temperature + "\u00b0C";
    $("#sliderHumidityVal").textContent = v.humidity + "%";
    $("#sliderSolarVal").textContent    = formatNumber(v.solarGeneration) + " MW";
    $("#sliderGrowthVal").textContent   = (v.demandGrowth >= 0 ? "+" : "") + v.demandGrowth + "%";
}

async function executeSimulation() {
    var btn = $("#runSimBtn"), btnSpan = btn.querySelector("span"), btnIcon = btn.querySelector("i");
    btn.classList.add("loading"); btn.disabled = true;
    btnSpan.textContent = "ANALYZING...";
    if (btnIcon) btnIcon.setAttribute("data-lucide", "loader");
    if (typeof lucide !== 'undefined') { try { lucide.createIcons({ nodes: [btn] }); } catch(e) {} }
    var loader = btn.querySelector("i");
    if (loader) loader.style.animation = "spin 0.8s linear infinite";

    try {
        var params = getSliderValues();
        console.log("What-If params:", params);
        var result = await runWhatIfScenario(params);
        console.log("What-If result:", result);
        appState.scenario = result;

        var empty = $("#whatifEmpty"), results = $("#whatifResults");
        if (empty) empty.classList.add("hidden");
        if (results) results.classList.remove("hidden");

        var risk = calculateRisk(result.utilization);
        var simBaselineEl = $("#simBaseline"); if (simBaselineEl) simBaselineEl.textContent = formatNumber(result.baselinePeak) + " MW";
        var simPeakEl = $("#simPeak"); if (simPeakEl) simPeakEl.textContent = formatNumber(result.simulatedPeak) + " MW";

        var changeEl = $("#simChange"), prefix = result.change >= 0 ? "+" : "";
        if (changeEl) {
            changeEl.textContent = prefix + formatNumber(result.change) + " MW";
            changeEl.className = "result-change " + (result.change >= 0 ? "increase" : "decrease");
        }

        var simUtilEl = $("#simUtil"); if (simUtilEl) simUtilEl.textContent = result.utilization + "%";

        var statusEl = $("#simStatus");
        if (statusEl) {
            if (result.utilization > 100) { statusEl.textContent = "CAPACITY EXCEEDED"; statusEl.className = "result-status exceeded"; }
            else if (risk.class === "high") { statusEl.textContent = "HIGH UTILIZATION"; statusEl.className = "result-status warning"; }
            else { statusEl.textContent = "WITHIN CAPACITY"; statusEl.className = "result-status safe"; }
        }

        var impP = $("#impactPeak");
        if (impP) {
            impP.textContent = prefix + formatNumber(result.change) + " MW";
            impP.className = "impact-value " + (result.change >= 0 ? "negative" : "positive");
        }
        var margin = CONFIG.capacity - result.simulatedPeak;
        var impM = $("#impactMargin");
        if (impM) {
            impM.textContent = (margin >= 0 ? "+" : "") + formatNumber(margin) + " MW";
            impM.className = "impact-value " + (margin >= 0 ? "positive" : "negative");
        }
        var impS = $("#impactStatus");
        if (impS) {
            impS.textContent = risk.level;
            impS.className = "impact-value " + (risk.class === "critical" || risk.class === "high" ? "critical" : "");
        }

        renderWhatIfChart(result);
        showToast("Simulation complete", "success");
    } catch (err) {
        console.error("What-If simulation error:", err);
        showToast("Simulation failed: " + err.message, "error");
    } finally {
        btn.classList.remove("loading"); btn.disabled = false;
        btnSpan.textContent = "RUN SIMULATION";
        if (btnIcon) btnIcon.setAttribute("data-lucide", "play");
        if (loader) loader.style.animation = "";
        if (typeof lucide !== 'undefined') { try { lucide.createIcons({ nodes: [btn] }); } catch(e) {} }
    }
}


// =============================================
// 11. EVENT LISTENERS
// =============================================

function setupEventListeners() {
    // Mobile menu
    var menuBtn = $("#mobileMenuBtn"), sidebar = $("#sidebar"), overlay = $("#mobileOverlay");
    if (menuBtn) menuBtn.addEventListener("click", function () {
        sidebar.classList.toggle("open"); overlay.classList.toggle("visible");
    });
    if (overlay) overlay.addEventListener("click", function () {
        sidebar.classList.remove("open"); overlay.classList.remove("visible");
    });
    document.addEventListener("keydown", function (e) {
        if (e.key === "Escape" && sidebar) { sidebar.classList.remove("open"); if (overlay) overlay.classList.remove("visible"); }
    });

    // Refresh
    var refreshBtn = $("#refreshBtn");
    if (refreshBtn) refreshBtn.addEventListener("click", function () {
        showToast("Refreshing data\u2026", "info");
        initCurrentPage();
    });

    // VIEW GRID RISK button (overview page)
    var viewRiskBtn = $("#viewRiskBtn");
    if (viewRiskBtn) viewRiskBtn.addEventListener("click", function () { window.location.href = "risk.html"; });

    // Chart tabs (local toggle, no navigation)
    $$("[data-range]").forEach(function (tab) {
        tab.addEventListener("click", function () {
            tab.parentElement.querySelectorAll(".chart-tab").forEach(function (t) { t.classList.remove("active"); });
            tab.classList.add("active");
            showToast("Switched to " + tab.dataset.range.toUpperCase() + " view", "info");
        });
    });
    $$("[data-forecast-range]").forEach(function (tab) {
        tab.addEventListener("click", function () {
            tab.parentElement.querySelectorAll(".chart-tab").forEach(function (t) { t.classList.remove("active"); });
            tab.classList.add("active");
            showToast("Forecast range: " + tab.dataset.forecastRange.toUpperCase(), "info");
        });
    });

    // What-If sliders
    ["sliderTemp", "sliderHumidity", "sliderSolar", "sliderGrowth"].forEach(function (id) {
        var el = document.getElementById(id);
        if (el) el.addEventListener("input", updateSliderDisplay);
    });

    // Run Simulation
    var simBtn = $("#runSimBtn");
    if (simBtn) simBtn.addEventListener("click", executeSimulation);
}


// =============================================
// 12. PAGE-SPECIFIC INITIALIZATION
// =============================================

async function initCurrentPage() {
    var page = appState.currentPage;
    try {
        switch (page) {
            case "overview":
                var oData = await Promise.all([fetchForecast(), fetchWeather(), fetchRisk()]);
                appState.forecast = oData[0]; appState.weather = oData[1]; appState.risk = oData[2];
                updateOverviewDOMValues(oData[0], oData[1]);
                renderKPIs(oData[0], oData[2]);
                renderOverviewChart(oData[0]);
                renderDemandDrivers();
                renderAlerts();
                renderOffsetDonut(oData[1].solarGeneration, oData[0].peakDemand);
                renderWeatherSparkline();
                break;
            case "forecast":
                var fAll = await Promise.all([fetchForecast(), fetchMetrics()]);
                appState.forecast = fAll[0];
                updateForecastPageDOMValues(fAll[1]);
                renderForecastChart(fAll[0]);
                renderForecastTable(fAll[0]);
                break;
            case "risk":
                var rData = await fetchRisk();
                appState.risk = rData;
                renderRiskPage(rData);
                break;
            case "whatif":
                // Start by loading actual conditions to seed sliders and baseline
                var wiAll = await Promise.all([fetchForecast(), fetchWeather()]);
                appState.forecast = wiAll[0];
                appState.weather = wiAll[1];
                
                var sliderTemp = $("#sliderTemp"); if (sliderTemp) sliderTemp.value = wiAll[1].temperature;
                var sliderHum = $("#sliderHumidity"); if (sliderHum) sliderHum.value = wiAll[1].humidity;
                var sliderSol = $("#sliderSolar"); if (sliderSol) sliderSol.value = wiAll[1].solarGeneration;
                
                updateSliderDisplay();
                
                var simBaseline = $("#simBaseline"); if (simBaseline) simBaseline.textContent = formatNumber(wiAll[0].peakDemand) + " MW";
                var simUtil = $("#whatifBaselineUtil"); if (simUtil) simUtil.textContent = ((wiAll[0].peakDemand / CONFIG.capacity) * 100).toFixed(1) + "%";
                break;
            case "weather":
                var wAll = await Promise.all([fetchForecast(), fetchWeather()]);
                appState.forecast = wAll[0]; appState.weather = wAll[1];
                updateWeatherPageDOMValues(wAll[1]);
                renderWeatherTempChart(wAll[0]);
                renderDemandTempChart(wAll[0]);
                break;
            case "insights":
                var ins = await fetchInsights();
                appState.insights = ins;
                renderInsights(ins);
                break;
        }
        // Update last updated time
        var now = new Date();
        var lu = $("#lastUpdatedTime");
        if (lu) lu.textContent = now.toLocaleTimeString("en-IN", { hour: "2-digit", minute: "2-digit", hour12: false }) + " IST";
    } catch (err) {
        console.error("Failed to load page data:", err);
        showToast("Failed to load data. Please try again.", "error");
    }
}


// =============================================
// 13. MAIN INIT
// =============================================

function init() {
    buildAppShell();
    if (typeof lucide !== 'undefined') lucide.createIcons();
    updateDateTime();
    setInterval(updateDateTime, 1000);
    setupEventListeners();
    initCurrentPage();
}

document.addEventListener("DOMContentLoaded", init);
